classes:
{`hover:text-cyan-600 dark:hover:text-cyan-400 transition-colors truncate max-w-[140px] sm:max-w-[200px] ${
                    isLast
                      ? 'text-slate-900 dark:text-white font-bold'
                      : 'text-slate-500 dark:text-slate-400 font-medium'
                  }`}

{`flex items-center gap-2 px-4 py-2.5 rounded-xl text-xs sm:text-sm font-bold transition-all ${
                activePlatform === 'iphone'
                  ? 'bg-cyan-600 text-white shadow-md ring-1 ring-cyan-300'
                  : 'bg-slate-100 dark:bg-slate-900 text-slate-700 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-800'
              }`}

{`flex items-center gap-2 px-4 py-2.5 rounded-xl text-xs sm:text-sm font-bold transition-all ${
                activePlatform === 'android'
                  ? 'bg-cyan-600 text-white shadow-md ring-1 ring-cyan-300'
                  : 'bg-slate-100 dark:bg-slate-900 text-slate-700 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-800'
              }`}

{`flex items-center gap-2 px-4 py-2.5 rounded-xl text-xs sm:text-sm font-bold transition-all ${
                activePlatform === 'pc'
                  ? 'bg-cyan-600 text-white shadow-md ring-1 ring-cyan-300'
                  : 'bg-slate-100 dark:bg-slate-900 text-slate-700 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-800'
              }`}

{`flex items-center gap-2 px-4 py-2.5 rounded-xl text-xs sm:text-sm font-bold transition-all ${
                activePlatform === 'mac'
                  ? 'bg-cyan-600 text-white shadow-md ring-1 ring-cyan-300'
                  : 'bg-slate-100 dark:bg-slate-900 text-slate-700 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-800'
              }`}

{`flex-1 flex items-center justify-center gap-2 py-2.5 rounded-xl text-xs font-bold transition-all ${
              activeTab === 'packs'
                ? 'bg-cyan-600 text-white shadow-md'
                : 'text-slate-600 dark:text-slate-400 hover:text-black dark:hover:text-white hover:bg-slate-200 dark:hover:bg-slate-800'
            }`}

{`flex-1 flex items-center justify-center gap-2 py-2.5 rounded-xl text-xs font-bold transition-all ${
              activeTab === 'cut'
                ? 'bg-cyan-600 text-white shadow-md'
                : 'text-slate-600 dark:text-slate-400 hover:text-black dark:hover:text-white hover:bg-slate-200 dark:hover:bg-slate-800'
            }`}

{`flex-1 py-2 text-xs rounded-lg font-bold border transition-colors ${
                        reservePercent === pct
                          ? 'bg-cyan-600 text-white border-cyan-600'
                          : 'bg-slate-100 dark:bg-slate-950 border-slate-300 dark:border-slate-800 text-slate-700 dark:text-slate-400 hover:text-black dark:hover:text-white'
                      }`}

{`group relative flex items-center justify-between px-2.5 py-2 rounded-xl text-xs sm:text-sm font-medium transition-all ${
            isSelected
              ? 'bg-cyan-600 text-white font-bold shadow-md ring-1 ring-cyan-300'
              : depth === 0
              ? 'text-slate-900 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800/80 font-semibold bg-white dark:bg-slate-900/80 border border-slate-200 dark:border-slate-800/80 shadow-xs'
              : depth === 1
              ? 'text-slate-700 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800/90 hover:text-black dark:hover:text-white bg-slate-50 dark:bg-slate-900/40 border-l-2 border-slate-300 dark:border-slate-700'
              : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 hover:text-black dark:hover:text-slate-100 bg-transparent border-l-2 border-cyan-400 dark:border-cyan-500/40'
          }`}

{`p-1 rounded hover:bg-amber-100 dark:hover:bg-amber-600/30 transition-colors ${
                  isStartPage ? 'text-amber-600 dark:text-amber-400' : 'text-slate-400 hover:text-amber-600'
                }`}

{`w-full flex items-center justify-between px-4 py-3 rounded-xl font-bold text-sm transition-all shadow-md select-none ${
              selectedPageId === saleItem.id
                ? 'bg-rose-600 text-white ring-2 ring-rose-300 shadow-rose-600/40'
                : 'bg-rose-600 hover:bg-rose-500 text-white shadow-sm'
            }`}

{`w-full flex items-center justify-between px-4 py-3 rounded-xl font-bold text-sm transition-all shadow-md select-none ${
              selectedPageId === monthItem.id
                ? 'bg-amber-400 text-slate-950 ring-2 ring-amber-300 shadow-amber-500/40'
                : 'bg-amber-400 hover:bg-amber-300 text-slate-950 shadow-sm'
            }`}

{`flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-bold transition-all shrink-0 ${
                    isCurrent
                      ? 'bg-cyan-600 text-white shadow-md ring-1 ring-cyan-400'
                      : 'bg-slate-100 dark:bg-slate-950/70 hover:bg-slate-200 dark:hover:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-800'
                  }`}

{`text-[9px] px-1 py-0.2 rounded font-semibold border ${getStatusBadgeStyle(
                        sibling.statusBadge
                      )}`}

{`p-2.5 sm:p-3.5 border-b-2 border-r border-slate-300 dark:border-slate-700/60 uppercase tracking-wider text-[11px] sm:text-xs select-none transition-colors ${headerStyle} ${
                      isFirst
                        ? 'sticky left-0 top-0 z-30 shadow-[3px_0_10px_rgba(0,0,0,0.1)] dark:shadow-[3px_0_10px_rgba(0,0,0,0.6)] w-[44vw] max-w-[45vw] min-w-[130px] sm:w-[240px] sm:max-w-[280px] sm:min-w-[200px]'
                        : 'sticky top-0 z-20 shadow-xs'
                    }`}

{`flex items-center gap-1.5 ${
                        col.align === 'center'
                          ? 'justify-center text-center'
                          : col.align === 'right'
                          ? 'justify-end text-right'
                          : 'justify-between'
                      }`}

{`p-2 sm:p-2.5 border-r border-slate-200 dark:border-slate-800/60 transition-colors ${
                            col.align === 'center'
                              ? 'text-center'
                              : col.align === 'right'
                              ? 'text-right font-mono'
                              : 'text-left'
                          } ${
                            isFirst
                              ? `sticky left-0 z-10 shadow-[3px_0_10px_rgba(0,0,0,0.06)] dark:shadow-[3px_0_10px_rgba(0,0,0,0.5)] ${stickyCellStyle} w-[44vw] max-w-[45vw] min-w-[130px] sm:w-[240px] sm:max-w-[280px] sm:min-w-[200px]`
                              : ''
                          }`}

{`w-full bg-slate-50 dark:bg-slate-950/60 hover:bg-white dark:hover:bg-slate-950 focus:bg-white dark:focus:bg-slate-950 border border-transparent hover:border-slate-300 dark:hover:border-slate-700 focus:border-cyan-500 rounded px-1.5 py-1 text-xs sm:text-sm text-slate-900 dark:text-slate-100 outline-none transition-colors ${
                                    col.align === 'center'
                                      ? 'text-center'
                                      : col.align === 'right'
                                      ? 'text-right font-mono'
                                      : 'text-left'
                                  }`}

{`w-full group/btn text-left flex items-start justify-between gap-1 p-1 rounded hover:bg-slate-200/60 dark:hover:bg-white/10 active:scale-95 transition-all cursor-pointer ${
                                col.align === 'center'
                                  ? 'justify-center text-center'
                                  : col.align === 'right'
                                  ? 'justify-end text-right'
                                  : ''
                              }`}

{`whitespace-normal break-words leading-snug text-xs sm:text-sm ${
                                  isFirst ? 'font-semibold' : ''
                                } ${
                                  isMatchingFilter ? 'bg-amber-200 dark:bg-amber-500/30 text-amber-900 dark:text-amber-200 px-1 rounded' : ''
                                }`}

{`p-2.5 rounded-xl border text-xs font-bold flex items-center justify-center gap-2 transition-all ${
                type === 'page'
                  ? 'bg-cyan-100 dark:bg-cyan-950 border-cyan-500 text-cyan-900 dark:text-cyan-300 ring-1 ring-cyan-400'
                  : 'bg-slate-50 dark:bg-slate-900 border-slate-200 dark:border-slate-800 text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800'
              }`}

{`p-2.5 rounded-xl border text-xs font-bold flex items-center justify-center gap-2 transition-all ${
                type === 'group'
                  ? 'bg-amber-100 dark:bg-amber-950 border-amber-500 text-amber-950 dark:text-amber-300 ring-1 ring-amber-400'
                  : 'bg-slate-50 dark:bg-slate-900 border-slate-200 dark:border-slate-800 text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800'
              }`}

{`flex items-center justify-between p-2 rounded-xl text-xs sm:text-sm transition-all hover:bg-slate-100 dark:hover:bg-slate-800/80 border ${
            depth === 0
              ? 'bg-slate-100 dark:bg-slate-900 border-slate-300 dark:border-slate-700 font-bold text-slate-900 dark:text-white'
              : depth === 1
              ? 'bg-slate-50 dark:bg-slate-950/70 border-slate-200 dark:border-slate-800 text-slate-800 dark:text-slate-200'
              : 'bg-white dark:bg-slate-950/40 border-slate-200 dark:border-slate-800/60 text-slate-700 dark:text-slate-300'
          }`}

{`w-full px-3.5 py-2.5 rounded-xl bg-slate-50 dark:bg-slate-950 border text-sm text-slate-900 dark:text-white outline-none transition-colors ${
                  error
                    ? 'border-rose-500 focus:border-rose-500'
                    : 'border-slate-300 dark:border-slate-700 focus:border-cyan-500'
                }`}

{`py-2 px-3 rounded-xl border text-xs font-bold transition-all ${
                  position === 'top'
                    ? 'bg-cyan-100 dark:bg-cyan-950 border-cyan-500 text-cyan-900 dark:text-cyan-300 ring-1 ring-cyan-400'
                    : 'bg-slate-50 dark:bg-slate-900 border-slate-200 dark:border-slate-800 text-slate-600 dark:text-slate-400'
                }`}

{`py-2 px-3 rounded-xl border text-xs font-bold transition-all ${
                  position === 'bottom'
                    ? 'bg-cyan-100 dark:bg-cyan-950 border-cyan-500 text-cyan-900 dark:text-cyan-300 ring-1 ring-cyan-400'
                    : 'bg-slate-50 dark:bg-slate-900 border-slate-200 dark:border-slate-800 text-slate-600 dark:text-slate-400'
                }`}

{`p-2.5 rounded-xl border text-xs font-bold flex flex-col items-center gap-1 transition-all ${
                  type === 'danger'
                    ? 'bg-rose-100 dark:bg-rose-950 border-rose-500 text-rose-900 dark:text-rose-200 ring-1 ring-rose-400'
                    : 'bg-slate-50 dark:bg-slate-900 border-slate-200 dark:border-slate-800 text-slate-600 dark:text-slate-400'
                }`}

{`p-2.5 rounded-xl border text-xs font-bold flex flex-col items-center gap-1 transition-all ${
                  type === 'warning'
                    ? 'bg-amber-100 dark:bg-amber-950 border-amber-500 text-amber-950 dark:text-amber-200 ring-1 ring-amber-400'
                    : 'bg-slate-50 dark:bg-slate-900 border-slate-200 dark:border-slate-800 text-slate-600 dark:text-slate-400'
                }`}

{`p-2.5 rounded-xl border text-xs font-bold flex flex-col items-center gap-1 transition-all ${
                  type === 'info'
                    ? 'bg-cyan-100 dark:bg-cyan-950 border-cyan-500 text-cyan-900 dark:text-cyan-200 ring-1 ring-cyan-400'
                    : 'bg-slate-50 dark:bg-slate-900 border-slate-200 dark:border-slate-800 text-slate-600 dark:text-slate-400'
                }`}

{`p-2.5 rounded-xl border text-xs font-bold flex flex-col items-center gap-1 transition-all ${
                  type === 'success'
                    ? 'bg-emerald-100 dark:bg-emerald-950 border-emerald-500 text-emerald-900 dark:text-emerald-200 ring-1 ring-emerald-400'
                    : 'bg-slate-50 dark:bg-slate-900 border-slate-200 dark:border-slate-800 text-slate-600 dark:text-slate-400'
                }`}

{`flex items-center gap-1.5 px-3.5 py-1.5 rounded-lg text-xs font-bold transition-all ${
              copied
                ? 'bg-emerald-600 text-white'
                : 'bg-cyan-600 hover:bg-cyan-500 text-white shadow-md'
            }`}

{`p-2.5 rounded-xl text-xs font-medium flex items-center gap-2 animate-in fade-in ${
                pingState.ok
                  ? 'bg-emerald-50 dark:bg-emerald-950/60 border border-emerald-300 dark:border-emerald-500/40 text-emerald-800 dark:text-emerald-300'
                  : 'bg-rose-50 dark:bg-rose-950/60 border border-rose-300 dark:border-rose-500/40 text-rose-800 dark:text-rose-300'
              }`}
